// ---------- DOM ----------
const resultsContainer = document.getElementById('resultsContainer');

// ---------- IMMEDIATE RENDER (no waiting, no spinner) ----------
function render() {
    if (!resultsContainer) {
        console.error('MyUniGuideSA: #resultsContainer not found in the page.');
        return;
    }

    try {
        const name = localStorage.getItem('uniPath_name');
        const grade = localStorage.getItem('uniPath_grade');
        const subjectsRaw = localStorage.getItem('uniPath_subjects');

        if (!name || !grade || !subjectsRaw) {
            resultsContainer.innerHTML = `
                <div class="no-results" style="padding:1.5rem; text-align:center; color:#94a9c4;">
                    <p style="font-size:1.1rem; margin-bottom:0.5rem;">⚠️ No learner data found.</p>
                    <p style="margin-top:0.5rem;">Please <a href="index.html" style="color:#60a5fa; font-weight:600;">go back</a> and enter your details first.</p>
                </div>
            `;
            return;
        }

        let subjects;
        try {
            subjects = JSON.parse(subjectsRaw);
        } catch (e) {
            resultsContainer.innerHTML = `<div class="no-results" style="padding:1.5rem; text-align:center; color:#94a9c4;">⚠️ Could not read your saved subjects.</div>`;
            return;
        }

        if (!Array.isArray(subjects) || subjects.length < 7) {
            resultsContainer.innerHTML = `<div class="no-results" style="padding:1.5rem; text-align:center; color:#94a9c4;">⚠️ Please enter at least 7 subjects on the details page. You have ${subjects ? subjects.length : 0}.</div>`;
            return;
        }

        const { aps, recommendations } = generateRecommendations(subjects);
        renderResults(aps, recommendations, name, grade);

    } catch (err) {
        console.error('Error:', err);
        resultsContainer.innerHTML = `
            <div class="no-results" style="padding:1.5rem; text-align:center; color:#94a9c4;">
                <p>⚠️ Something went wrong.</p>
                <p style="margin-top:0.5rem; font-family: monospace; font-size: 0.85rem; color:#f87171;">${escapeHtml(err.message)}</p>
                <p style="margin-top:0.8rem;"><a href="index.html" style="color:#60a5fa; font-weight:600;">← Back to my details</a></p>
            </div>
        `;
    }
}

// ---------- CALCULATE APS ----------
function calculateAPS(subjects) {
    if (subjects.length === 0) return 0;
    const academicSubjects = subjects.filter(s => s.subject !== "Life Orientation");
    if (academicSubjects.length === 0) return 0;

    const marks = academicSubjects.map(s => s.mark).sort((a, b) => b - a);
    const bestSix = marks.slice(0, 6);

    let aps = 0;
    bestSix.forEach(mark => {
        if (mark >= 90) aps += 8;
        else if (mark >= 80) aps += 7;
        else if (mark >= 70) aps += 6;
        else if (mark >= 60) aps += 5;
        else if (mark >= 50) aps += 4;
        else if (mark >= 40) aps += 3;
        else if (mark >= 30) aps += 2;
        else aps += 1;
    });
    return aps;
}

// ---------- CHECK REQUIREMENTS ----------
function checkRequirements(course, subjects) {
    if (!course.requirements || course.requirements.length === 0) {
        return { met: true, missing: [] };
    }

    // Normalize learner subjects
    const normalized = subjects.map(s => ({
        subject: String(s.subject || '').trim(),
        mark: Number(s.mark)
    })).filter(s => s.subject && !Number.isNaN(s.mark));

    function markForExact(name) {
        let best = -1;
        const target = name.trim().toLowerCase();
        for (const s of normalized) {
            if (s.subject.toLowerCase() === target) best = Math.max(best, s.mark);
        }
        return best;
    }

    function markForPredicate(pred) {
        let best = -1;
        for (const s of normalized) {
            if (pred(s.subject)) best = Math.max(best, s.mark);
        }
        return best;
    }

    function resolveRequirement(reqSubject) {
        const alternatives = reqSubject.split(/\s+OR\s+/i).map(a => a.trim()).filter(Boolean);
        let bestMark = -1;

        for (const alt of alternatives) {
            // Exact match
            bestMark = Math.max(bestMark, markForExact(alt));

            const lower = alt.toLowerCase();

            // English (HL or FAL)
            if (/english/.test(lower) && /(home language|first additional)/.test(lower)) {
                bestMark = Math.max(bestMark, markForPredicate(s =>
                    /english/i.test(s) && /(home language|first additional)/i.test(s)
                ));
            }
            // Any English subject if requirement just says English
            if (lower === 'english' || lower === 'english language') {
                bestMark = Math.max(bestMark, markForPredicate(s => /english/i.test(s)));
            }
            // Mathematics OR Mathematical Literacy handled by split, also soft-match
            if (lower === 'mathematics') {
                bestMark = Math.max(bestMark, markForExact('Mathematics'));
            }
            if (lower === 'mathematical literacy') {
                bestMark = Math.max(bestMark, markForExact('Mathematical Literacy'));
            }
            // Physical Sciences / Life Sciences soft
            if (lower === 'physical sciences') {
                bestMark = Math.max(bestMark, markForExact('Physical Sciences'));
            }
            if (lower === 'life sciences') {
                bestMark = Math.max(bestMark, markForExact('Life Sciences'));
            }
            // Additional Language generic
            if (lower === 'additional language') {
                bestMark = Math.max(bestMark, markForPredicate(s =>
                    /home language|first additional language/i.test(s)
                ));
            }
            // Home language generic — any * Home Language
            if (lower === 'home language') {
                bestMark = Math.max(bestMark, markForPredicate(s => /home language/i.test(s)));
            }
        }
        return bestMark;
    }

    const missing = [];
    for (const req of course.requirements) {
        const minP = Number(req.minPercent) || 0;
        const bestMark = resolveRequirement(req.subject || '');
        if (bestMark < 0) {
            missing.push({ subject: req.subject, reason: 'not taken', required: minP });
        } else if (bestMark < minP) {
            missing.push({ subject: req.subject, reason: `only ${bestMark}%`, required: minP });
        }
    }
    return { met: missing.length === 0, missing };
}

// ---------- GENERATE ----------
function generateRecommendations(subjects) {
    const aps = calculateAPS(subjects);
    const recommendations = [];

    universityCourses.forEach(uni => {
        const uniFaculties = [];
        uni.faculties.forEach(faculty => {
            const allCourses = faculty.courses.map(course => {
                const apsMet = aps >= course.aps;
                const reqCheck = checkRequirements(course, subjects);
                const qualified = apsMet && reqCheck.met;
                return { ...course, apsMet, reqCheck, qualified };
            });

            allCourses.sort((a, b) => {
                if (a.qualified && !b.qualified) return -1;
                if (!a.qualified && b.qualified) return 1;
                return b.aps - a.aps;
            });

            uniFaculties.push({ facultyName: faculty.name, courses: allCourses });
        });

        recommendations.push({ university: uni.university, faculties: uniFaculties });
    });

    return { aps, recommendations };
}

// ---------- RENDER RESULTS ----------

// Simple stroke icons (no emoji)
const ICONS = {
  uni: '<span class="ico" aria-hidden="true">⌂</span>',
  book: '<span class="ico" aria-hidden="true">▣</span>',
  check: '<span class="ico" aria-hidden="true">✓</span>',
  cross: '<span class="ico" aria-hidden="true">✕</span>',
  clock: '<span class="ico" aria-hidden="true">◷</span>',
  filter: '<span class="ico" aria-hidden="true">☰</span>',
};

function formatJobsHtml(description) {
    if (!description) return { about: '', jobsHtml: '' };
    const parts = description.split(/Jobs:/i);
    const about = (parts[0] || '').trim();
    const jobsRaw = (parts[1] || '').trim();
    if (!jobsRaw) return { about, jobsHtml: '' };
    // Split on "; " between job entries
    const items = jobsRaw.replace(/\.$/, '').split(/;\s*/).map(s => s.trim()).filter(Boolean);
    if (!items.length) return { about, jobsHtml: '' };
    const lis = items.map(item => `<li>${escapeHtml(item)}</li>`).join('');
    return {
        about,
        jobsHtml: `<p class="jobs-title">Jobs</p><ul class="jobs-list">${lis}</ul>`
    };
}

function slugifyUniversity(name) {
    return 'uni-' + name.toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/(^-|-$)/g, '');
}

function renderResults(aps, recommendations, learnerName, grade) {
    let qualifiedCount = 0;
    let totalCount = 0;
    recommendations.forEach(uni => {
        uni.faculties.forEach(fac => {
            fac.courses.forEach(c => {
                totalCount++;
                if (c.qualified) qualifiedCount++;
            });
        });
    });

        // Toolbar: filter + university search
    let navHtml = `
        <div class="results-toolbar" id="resultsToolbar">
            <div class="filter-row">
                <span class="filter-label">Show</span>
                <button type="button" class="filter-btn active" data-filter="all">All courses</button>
                <button type="button" class="filter-btn" data-filter="qualified">Qualified only</button>
            </div>
            <div class="uni-search-wrap">
                <label class="uni-search-label" for="uniSearchInput">${ICONS.uni} Search university</label>
                <div class="uni-search-box">
                    <input type="search" id="uniSearchInput" class="uni-search-input" placeholder="Type or tap to choose a university…" autocomplete="off">
                    <ul id="uniSearchList" class="uni-search-list" hidden></ul>
                </div>
            </div>
        </div>`;

    let html = `
        <div class="results-summary">
            <strong>${escapeHtml(learnerName)}</strong> · Grade ${escapeHtml(grade)} ·
            <span class="aps-pill">APS ${aps}</span>
            <span class="results-counts">${qualifiedCount} qualified · ${totalCount} total</span>
        </div>
        ${navHtml}
        <p class="disclaimer">APS and subject minima are typical published ranges — always verify with the official university prospectus for your intake year.</p>
    `;

    recommendations.forEach(uni => {
        const uniId = slugifyUniversity(uni.university);
        const meta = getUniMeta(uni.university);
        const provinceTag = meta.province
            ? `<span class="province-tag">${escapeHtml(meta.province)}</span>`
            : '';

        html += `<div class="university-block" id="${uniId}">`;
        html += `<div class="university-header">
            <div class="uni-header-left">
              <span class="uni-title">${ICONS.uni} ${escapeHtml(uni.university)}</span>
              ${provinceTag}
            </div>
        </div>`;

        uni.faculties.forEach(faculty => {
            html += `<div class="faculty-block">`;
            html += `<div class="faculty-header">${ICONS.book} ${escapeHtml(faculty.facultyName)}</div>`;

            faculty.courses.forEach((course, idx) => {
                const courseId = `course-${Date.now()}-${Math.random().toString(36).substr(2, 6)}-${idx}`;
                const qualifiedClass = course.qualified ? 'course-qualified' : 'course-not-qualified';
                const badge = course.qualified
                    ? `<span class="badge badge-yes">Qualified</span>`
                    : `<span class="badge badge-no">Not yet</span>`;

                let reqHtml = '';
                if (course.requirements && course.requirements.length > 0) {
                    reqHtml = `<p style="margin-top:0.5rem;"><strong>Minimum subject requirements:</strong></p><ul>`;
                    course.requirements.forEach(req => {
                        const missingForReq = course.reqCheck.missing.find(m => m.subject === req.subject);
                        const passed = !missingForReq;
                        const icon = passed ? '✅' : '❌';
                        const detail = missingForReq
                            ? `<span class="req-fail"> (${missingForReq.reason}, need ${missingForReq.required}%)</span>`
                            : '';
                        reqHtml += `<li>${icon} ${escapeHtml(req.subject)}: ${req.minPercent}% minimum${detail}</li>`;
                    });
                    reqHtml += `</ul>`;
                } else {
                    reqHtml = `<p style="margin-top:0.5rem;">No specific subject requirements listed.</p>`;
                }

                const apsFeedback = course.apsMet
                    ? `<span class="aps-ok">Your APS (${aps}) meets the required ${course.aps}.</span>`
                    : `<span class="aps-bad">Your APS (${aps}) is below the required ${course.aps}. Need ${course.aps - aps} more point${(course.aps - aps) !== 1 ? 's' : ''}.</span>`;

                html += `
                    <div class="course-wrap" data-qualified="${course.qualified ? '1' : '0'}">
                    <div class="course-item ${qualifiedClass}" data-course-id="${courseId}" data-qualified="${course.qualified ? '1' : '0'}">
                        <div class="course-info">
                            <span class="course-name">${escapeHtml(course.name)}</span>
                            <span class="course-aps">APS ${course.aps}</span>
                            ${course.duration ? `<span class="course-duration">${ICONS.clock} ${escapeHtml(course.duration)}</span>` : ''}
                            ${badge}
                        </div>
                        <button type="button" class="arrow-btn" data-target="${courseId}" aria-expanded="false">▼</button>
                    </div>
                    <div class="course-desc" id="${courseId}" hidden>
                        ${(() => { const fj = formatJobsHtml(course.description); return `<p><strong>About this course:</strong> ${escapeHtml(fj.about)}</p>${fj.jobsHtml}`; })()}
                        <p style="margin-top:0.4rem;">${apsFeedback}</p>
                        ${reqHtml}
                    </div>
                    </div>
                `;
            });

            html += `</div></div>`; /* close faculty-body + faculty-block */
        });

        html += `</div>`; /* close university-block */
    });

    resultsContainer.innerHTML = html;

    // Filter: All / Qualified only
    function applyFilter(mode) {
        document.querySelectorAll('.filter-btn').forEach(b => {
            b.classList.toggle('active', b.getAttribute('data-filter') === mode);
        });
        document.querySelectorAll('.course-wrap').forEach(wrap => {
            const q = wrap.getAttribute('data-qualified') === '1';
            const show = mode === 'all' || q;
            wrap.style.display = show ? '' : 'none';
            if (!show) {
                const desc = wrap.querySelector('.course-desc');
                const btn = wrap.querySelector('.arrow-btn');
                if (desc) { desc.hidden = true; desc.classList.remove('show'); }
                if (btn) { btn.textContent = '▼'; btn.setAttribute('aria-expanded', 'false'); }
            }
        });
        // Hide empty faculty blocks
        document.querySelectorAll('.faculty-block').forEach(fac => {
            const visible = Array.from(fac.querySelectorAll('.course-wrap')).some(w => w.style.display !== 'none');
            fac.style.display = visible ? '' : 'none';
        });
        document.querySelectorAll('.university-block').forEach(block => {
            const visible = Array.from(block.querySelectorAll('.course-wrap')).some(w => w.style.display !== 'none');
            block.style.display = visible ? '' : 'none';
        });
    }

    document.querySelectorAll('.filter-btn').forEach(btn => {
        btn.addEventListener('click', () => applyFilter(btn.getAttribute('data-filter')));
    });

    // University search list
    (function setupUniSearch() {
        const input = document.getElementById('uniSearchInput');
        const list = document.getElementById('uniSearchList');
        if (!input || !list) return;

        const unis = recommendations.map(u => ({
            name: u.university,
            id: slugifyUniversity(u.university)
        }));

        function renderList(filter) {
            const q = (filter || '').trim().toLowerCase();
            const items = unis.filter(u => !q || u.name.toLowerCase().includes(q));
            if (!items.length) {
                list.innerHTML = '<li class="uni-search-empty">No university found</li>';
            } else {
                list.innerHTML = items.map(u =>
                    `<li class="uni-search-item" data-id="${u.id}" data-name="${escapeHtml(u.name)}">${escapeHtml(u.name)}</li>`
                ).join('');
            }
            list.hidden = false;
        }

        function goToUni(id) {
            const el = document.getElementById(id);
            if (!el) return;
            list.hidden = true;
            el.scrollIntoView({ behavior: 'smooth', block: 'start' });
            el.classList.add('uni-highlight');
            setTimeout(() => el.classList.remove('uni-highlight'), 1200);
        }

        input.addEventListener('focus', () => renderList(input.value));
        input.addEventListener('click', () => renderList(input.value));
        input.addEventListener('input', () => renderList(input.value));

        list.addEventListener('click', (e) => {
            const item = e.target.closest('.uni-search-item');
            if (!item) return;
            input.value = item.getAttribute('data-name') || item.textContent;
            goToUni(item.getAttribute('data-id'));
        });

        document.addEventListener('click', (e) => {
            if (!e.target.closest('.uni-search-box')) list.hidden = true;
        });
    })();

    function setDescOpen(descEl, btn, open) {
        if (!descEl) return;
        if (open) {
            descEl.hidden = false;
            descEl.classList.add('show');
            if (btn) { btn.textContent = '▲'; btn.setAttribute('aria-expanded', 'true'); }
        } else {
            descEl.hidden = true;
            descEl.classList.remove('show');
            if (btn) { btn.textContent = '▼'; btn.setAttribute('aria-expanded', 'false'); }
        }
    }

    document.querySelectorAll('.course-desc').forEach(desc => setDescOpen(desc, null, false));
    document.querySelectorAll('.arrow-btn').forEach(btn => {
        btn.textContent = '▼';
        btn.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            const descEl = document.getElementById(btn.getAttribute('data-target'));
            const open = descEl && !descEl.hidden && descEl.classList.contains('show');
            setDescOpen(descEl, btn, !open);
        });
    });

    document.querySelectorAll('.course-item').forEach(item => {
        item.addEventListener('click', (e) => {
            if (e.target.closest('.arrow-btn')) return;
            const btn = item.querySelector('.arrow-btn');
            if (btn) btn.click();
        });
    });

    // Faculties: open by default; click header to collapse/expand course list
    document.querySelectorAll('[data-fac-toggle]').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            const id = btn.getAttribute('data-fac-toggle');
            const body = document.getElementById(id);
            const block = btn.closest('.faculty-block');
            if (!body || !block) return;
            const open = block.classList.contains('open');
            if (open) {
                block.classList.remove('open');
                body.hidden = true;
                btn.setAttribute('aria-expanded', 'false');
                const chev = btn.querySelector('.faculty-chevron');
                if (chev) chev.textContent = '▶';
            } else {
                block.classList.add('open');
                body.hidden = false;
                btn.setAttribute('aria-expanded', 'true');
                const chev = btn.querySelector('.faculty-chevron');
                if (chev) chev.textContent = '▼';
            }
        });
    });
}

// ---------- UTILITY ----------
function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

// ---------- RUN IMMEDIATELY ----------
// The script is at the end of <body>, so the DOM is ready.
// We call render() directly — no waiting, no spinner.
render();